   317                  if (!newstr) {
   318                      IGRAPH_ERROR("Cannot add attributes", IGRAPH_ENOMEM);
   319                  }
   320                  IGRAPH_FINALLY(igraph_free, newstr);
   321                  IGRAPH_STRVECTOR_INIT_FINALLY(newstr, origlen);
   322                  newrec->value = newstr;
   323              } else if (type == IGRAPH_ATTRIBUTE_BOOLEAN) {
   324                  igraph_vector_bool_t *newbool = igraph_Calloc(1, igraph_vector_bool_t);
   325                  if (!newbool) {
   326                      IGRAPH_ERROR("Cannot add attributes", IGRAPH_ENOMEM);
   327                  }
   328                  IGRAPH_FINALLY(igraph_free, newbool);
   329                  IGRAPH_CHECK(igraph_vector_bool_init(newbool, origlen));
   330                  IGRAPH_FINALLY(igraph_vector_bool_destroy, newbool);
   331                  newrec->value = newbool;
   332                  igraph_vector_bool_fill(newbool, 0);
   333              }
