   436              igraph_vector_bool_t *boolv = (igraph_vector_bool_t*) rec->value;
   437              igraph_vector_bool_destroy(boolv);
   438              igraph_Free(boolv);
   439          }
   440          igraph_Free(rec);
   441      }
   442      igraph_vector_ptr_clear(v);
   443  }
